style.css:
@-moz-document domain("netflix.com") {
.profile-gate-container,
  .profile-selection-container {
    background-color: #002833 !important;
    background-image: none !important;
  }

  .profile-icon,
  .profile-name {
    border-color: #004466 !important;
    color: #aaddff !important;
  }

  .profile-icon:hover {
    box-shadow: 0 0 10px #004466 !important;
  }

  .profile-gate-header {
    color: #aaddff !important;
    text-shadow: 1px 1px 2px black;
  }

  .profile-manage-button {
    color: #aaddff !important;
  }
}
